			/**
			 * 개정된 평가내역 설정
			 * 
			 * @param {cpr.data.DataSet} dataSet    데이터셋
			 */
			function setRvsnEvl(/* cpr.data.DataSet */ dataSet) {
			   
			    var sumScore = 0;
			    // 채팅상담 평가내역 설정
			    var chttEvlYn = dataSet.getValue(0, "CHTT_EVL_YN");
			    if (chttEvlYn == "Y") {
			        var dmViewChatEvlArea = app.lookup("dmViewChatEvlArea");
			        var chatEvlchkListQuests = app.lookup("dsChatEvlChkListQuest").getRowDataRanged();
			        //console.log("chatEvlchkListQuests : ", chatEvlchkListQuests);
			        for (idx in chatEvlchkListQuests) {
			            var item = chatEvlchkListQuests[idx];
			            var rowNum = item["ROW_NUM"];
			            
			            sumScore += Number(item["CHKLST_SCORE"]);
			            
			            var columnName = "CHKLIST_QUEST" + rowNum + "_SCORE";
			            dmViewChatEvlArea.setValue(columnName, item["CHKLST_SCORE"]);
			            
			            columnName = "CHKLIST_QUEST" + rowNum + "_CN";
			            dmViewChatEvlArea.setValue(columnName, item["CHKLST_CN"]);
			        }
			        sumScore += Number(dataSet.getValue(0, "CHTT_OVERAL_RELEVA_SCORE"));
			        
			        dmViewChatEvlArea.setValue("SUM_CHKLST_SCORE", sumScore);
			        dmViewChatEvlArea.setValue("CHTT_OVERAL_RELEVA_SCORE", dataSet.getValue(0, "CHTT_OVERAL_RELEVA_SCORE"));
			        dmViewChatEvlArea.setValue("CHTT_DSCSN_EVL_THTS_PLAN_CN", dataSet.getValue(0, "CHTT_DSCSN_EVL_THTS_PLAN_CN"));
			        
			        console.log("dmViewChatEvlArea : ", dmViewChatEvlArea.getDatas());
			    }
			    
			    // 게시판상담 평가내역 설정
			    var ntabrdEvlYn = dataSet.getValue(0, "NTABRD_EVL_YN");
			    if (ntabrdEvlYn == "Y") {
			        sumScore = 0;
			        
			        var dmViewNtabrdEvlArea = app.lookup("dmViewNtabrdEvlArea");
			        var ntabrdchkListQuests = app.lookup("dsNtabrdEvlChkListQuest").getRowDataRanged();
			        //console.log("ntabrdchkListQuests : ", ntabrdchkListQuests);
			        for (idx in ntabrdchkListQuests) {
			            var item = ntabrdchkListQuests[idx];
			            var rowNum = item["ROW_NUM"];
			            
			            sumScore += Number(item["CHKLST_SCORE"]);
			            
			            var columnName = "CHKLIST_QUEST" + rowNum + "_SCORE";
			            dmViewNtabrdEvlArea.setValue(columnName, item["CHKLST_SCORE"]);
			            
			            columnName = "CHKLIST_QUEST" + rowNum + "_CN";
			            dmViewNtabrdEvlArea.setValue(columnName, item["CHKLST_CN"]);
			        }
			        sumScore += Number(dataSet.getValue(0, "NTABRD_OVERAL_RELEVA_SCORE"));
			        
			        dmViewNtabrdEvlArea.setValue("SUM_CHKLST_SCORE", sumScore);
			        dmViewNtabrdEvlArea.setValue("NTABRD_OVERAL_RELEVA_SCORE", dataSet.getValue(0, "NTABRD_OVERAL_RELEVA_SCORE"));
			        dmViewNtabrdEvlArea.setValue("NTABRD_DSCSN_EVL_THTS_PLAN_CN", dataSet.getValue(0, "NTABRD_DSCSN_EVL_THTS_PLAN_CN"));
			        
			        console.log("dmViewNtabrdEvlArea : ", dmViewNtabrdEvlArea.getDatas());
			    }
			}

