			/**
			 * Form 컨트롤 ID 조회
			 * 
			 * @param {cpr.core.AppInstance} app 앱인스턴스
			 * @param {String} psGrpId 그룹 ID
			 * @param {cpr.controls.ControlType} psType
			 */
			function getFrmControlId(app, paGrpId, psType) {
			    /** @type cpr.controls.Container */
			    var _container = app.lookup(paGrpId);
			    if (_container == undefined || !(typeof cpr.controls.Container)) {
			        throw new Error("Unknown Control Type!");
			    }
			    
			    var ctrlIdx = _container.getChildren().findIndex(function(element, index, arr){
			    	return element.type == psType;
			    });
			    
			    var ctrlObj = {
			        id : app.lookup(paGrpId).getChildren()[ctrlIdx].id,
			        type : app.lookup(paGrpId).getChildren()[ctrlIdx].type,
			    };
			    console.log(ctrlObj);
			    
			    return ctrlObj.id;
			}

			/**
			 * 변경사항을 체크합니다.
			 * @return {Boolean} 변경유무
			 */
			function _isModified() {
			    
			    var dmCmmnReportDtl = app.lookup("dmCmmnReportDtl");
			    var dsReportDtl = app.lookup("dsReportDtl");
			    var dsMobileEditDtl = app.lookup("dsMobileEditDtl");
			    
			    var vsContent = dmCmmnReportDtl.getValue("ETC_DTL_CN")
			    var vsBeforeCont = dsReportDtl.getValue(0, "ETC_DTL_CN");
			    
			    var isModified = false;
			    
			    if (vsContent != vsBeforeCont) {
			        isModified = true;
			    } else if (dsMobileEditDtl.isModified()) {
			        isModified = true;
			    }
			    
			    return isModified;
			}

			/**
			 * 포멧팅 문자열을 반환한다.
			 * 
			 * @param {String} psValue  포멧팅 대상 문자열
			 * 
			 * @return {String} 포멧팅된 문자열
			 */
			function toFmtString(psValue) {
			    if (psValue == undefined) return "";
			    else if (arguments <= 1) return psValue;
			    
			    var formatted = psValue, i = 1;
			    while (/%s/.test(formatted)) {
			        formatted = formatted.replace("%s", arguments[i++]);
			    }
			    return formatted;
			}

