			/*
			 * 루트 컨테이너에서 init 이벤트 발생 시 호출.
			 * 앱이 최초 구성될 때 발생하는 이벤트 입니다.
			 */
			function onBodyInit(/* cpr.events.CEvent */ e) {
			    var voInitValue = app.getHostProperty("initValue");
			    console.log("voInitValue : ", voInitValue);
			    
			    // 2022-12-13 (Myeong.Jae.Cheol) : 모니터링 보고서 상세 진입 추가
			    var viewType = "";
			    if (voInitValue.reqViewType) {
			        viewType = voInitValue.reqViewType;
			    }
			    
			    if (viewType == "mntrgReprtDetail") {
			        // 모니터링 보고서 상세 (관리자)
			        var data = voInitValue.selectedRowData;
			        app.setAppProperty("deptCd", data["OGDP_DEPT_CD"]);
			        this.mbCnsltntAdmin = true;
			    } else {
			        // 업무보고서 목록
			        
			        // 앱 속성 설정 (부서코드)
			        var userGroupAuthrt = util.Auth.getUserInfo(app, "GROUP_AUTHRT_SE_CD");     // 그룹권한구분코드
			        var deptCd = util.Auth.getUserInfo(app, "DEPT_CD");                         // 부서코드
			        
			        // 상담관리자인 경우 목록화면에서 넘어온 부서코드 설정
			        if (userGroupAuthrt == "340") {
			            app.setAppProperty("deptCd", deptCd);
			            this.mbCnsltntAdmin = false;
			        } else {
			            app.setAppProperty("deptCd", voInitValue["DEPT_CD"]);
			            this.mbCnsltntAdmin = true;
			        }
			        
			    }
			    
			    console.log("mbCnsltntAdmin : " + this.mbCnsltntAdmin);
			}

			/*
			 * 루트 컨테이너에서 load 이벤트 발생 시 호출.
			 * 앱이 최초 구성된후 최초 랜더링 직후에 발생하는 이벤트 입니다.
			 */
			function onBodyLoad(/* cpr.events.CEvent */ e) {
			    // 시간선택 콤보박스 초기화
			    for (var i = 0; i <= 59; i++) {
			        var currMin;
			        if (i < 10) {
			            currMin = "0" + i;
			        } else {
			            currMin = "" + i;
			        }
			        app.lookup("dsMinute").addRowData({ label: currMin, value: currMin });
			    }
			    
			    var voInitValue = app.getHostProperty("initValue");
			    console.log("voInitValue : ", voInitValue);
			    
			    // 앱 속성 설정 (부서코드)
			    var deptCd = app.getAppProperty("deptCd");
			    
			    var tab1 = app.lookup("tab1");
			    var tabItem = "";
			    
			    if (deptCd == "324") {  
			        // 사이버상담
			        msSelectFrmId = getFrmControlId(app, "grpContents", ControlType.CONTAINER);
			        
			        tab1.tabIndex = 0;
			        tabItem = tab1.getTabItemByID(1);
			        
			        tab1.getTabItemByID(2).visible = false;
			        tab1.getTabItemByID(3).visible = false;
			    } else if (deptCd == "325") {
			        // 사이버아웃리치
			        msSelectFrmId = getFrmControlId(app, "grpContents2", ControlType.CONTAINER);
			        
			        tab1.tabIndex = 1;
			        tabItem = tab1.getTabItemByID(2);
			        
			        tab1.getTabItemByID(1).visible = false;
			        tab1.getTabItemByID(3).visible = false;
			    } else {
			        // 모바일상담
			        msSelectFrmId = getFrmControlId(app, "grpContents3", ControlType.CONTAINER);
			        
			        tab1.tabIndex = 2;
			        tabItem = tab1.getTabItemByID(3);
			        
			        tab1.getTabItemByID(1).visible = false;
			        tab1.getTabItemByID(2).visible = false;        
			    }
			    
			    // 탭 영역 설정
			    tab1.setSelectedTabItem(tabItem);
			    tab1.visible = true;
			    util.Control.redraw(app, "tab1");
			    
			    if(voInitValue.selectedRowData){
			        var data = voInitValue.selectedRowData;
			        
			        app.lookup("dmSearch").setValue("TASKWK_REPRTS_INDEX_SN", data["TASKWK_REPRTS_INDEX_SN"]);
			        app.lookup("dmSearch").setValue("DEPT_CD", deptCd);
			        
			        // 게시판상담건수 > 다음게시판 건수 hide
			        app.lookup("grp2").getLayout().setRowVisible(1, false);

			        doList();
			        
			    }
			    
			    //app.lookup("grpTime").removeAllChildren(true);
			}


