			/*
			 * "저장" 버튼(btnSave)에서 click 이벤트 발생 시 호출.
			 * 사용자가 컨트롤을 클릭할 때 발생하는 이벤트.
			 */
			function onBtnSaveClick(e){
			    var btnSave = e.control;
			    var deptCd = app.getAppProperty("deptCd");
			    
			    var dmCmmnReportDtl = app.lookup("dmCmmnReportDtl");
			    var dsReportDtl = app.lookup("dsReportDtl");
			    var dsMobileEditDtl = app.lookup("dsMobileEditDtl");
			    
			    function fn_update_submit() {
			        
			        /** vcFileUpload1 (시작시간첨부파일) 전송후 콜백 */
			        function fn_fileUpload1Callback() {
			            var vcFileUpload2 = app.lookup('cmnsinglefileupload5');   // 종료시간첨부파일
			            if (vcFileUpload2.isFileModified()) {
			                vcFileUpload2.send(doSave);
			            } else {
			                doSave();
			            }
			        }
			        
			        // 시간이외근무신청 시 입증서류 첨부파일 전송
			        var ovtimeAplyYn = dsMobileEditDtl.getValue(0, "OVTIME_APLY_YN");
			        if (ovtimeAplyYn == "Y") {
			            var vcFileUpload1 = app.lookup('cmnsinglefileupload4');    // 시작시간첨부파일
			            if (vcFileUpload1.isFileModified()) {
			                vcFileUpload1.send(fn_fileUpload1Callback);
			            } else {
			                doSave();
			            }
			        } else {
			            doSave();
			        }
			        
			    };
			    
			    function fn_update_cancel() {
			        
			        // 데이터 셋 초기값 전환
			        dsMobileEditDtl.revert();
			        
			        // 바인딩된 데이터맵 초기화
			        dmCmmnReportDtl.setValue("ETC_DTL_CN", dsReportDtl.getValue(0, "ETC_DTL_CN"));
			            
			        util.Control.redraw(app, msSelectFrmId);
			        
			        setDetailInfo("READ");
			    };
			    
			    if (msReprtsDtlType == "UPDATE") {
			        // 변경 사항 체크
			//        if (!_isModified()) {
			//            util.Msg.alert(app, "INF-M006", null, fn_update_cancel);
			//            return false;
			//        }

			        var etcDtlCnTextArea = getEtcCnTextAreaId(deptCd);
			        var etcDtlCn = app.lookup(etcDtlCnTextArea).getValue();
			        
			        if (deptCd == "324" || deptCd == "325") {
			            // 사이버상담, 사이버아웃리치
			            // dmCmmnReportDtl.getValue("ETC_DTL_CN");
			            var indexSn = util.DataSet.getValue(app, "dsReportDtl", 0, "TASKWK_REPRTS_INDEX_SN");
			            var latenCn = util.DataMap.getValue(app, "dmCmmnReportDtl", "LATEN_CN");
			            var voRowData = {
			                "TASKWK_REPRTS_INDEX_SN" : indexSn,
			                "LATEN_CN" : latenCn,
			                "ETC_DTL_CN" : etcDtlCn,
			            };
			            
			            var rowCount = util.DataSet.getRowCount(app, "dsReportDtl");
			            console.log("dsReportDtl.rowCount: ", rowCount);
			            if (rowCount == 1) {
			                util.DataSet.insertRow(app, "dsReportDtl", 1, false, voRowData);
			                dsReportDtl.setRowState(1, RowState.UPDATED);    
			            } else {
			                dsReportDtl.getRow(1).setRowData(voRowData);
			            }
			            console.log("dsReportDtl.getRowData: ", dsReportDtl.getRowData(1));
			            
			        } else if (deptCd == "326") {
			            dsMobileEditDtl.setValue(0, "ETC_DTL_CN", etcDtlCn);
			        }
			        
			        // 유효성 체크
			        if (!util.validate(app, msSelectFrmId)) return;
			        
			        // 모바일상담 데이터 셋 로우상태 체크
			        var rowState = dsMobileEditDtl.getRowState(0);
			        console.log("dsMobileEditDtl: rowState=", rowState);
			        console.log("dsMobileEditDtl: ", dsMobileEditDtl.getRowDataRanged());
			        
			        util.Msg.confirm(app, "업무 보고서를 수정하시겠습니까?", null, fn_update_submit, fn_update_cancel);
			    }
			}

